-- Logical schema summary. SQLAlchemy creates these tables at startup.
CREATE TABLE users (id INT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(255) UNIQUE NOT NULL, full_name VARCHAR(160) NOT NULL, hashed_password VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL, is_active BOOLEAN NOT NULL, session_version VARCHAR(32) NOT NULL DEFAULT '');
CREATE TABLE departments (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) UNIQUE NOT NULL, description VARCHAR(255));
CREATE TABLE employees (id INT PRIMARY KEY AUTO_INCREMENT, employee_code VARCHAR(30) UNIQUE NOT NULL, full_name VARCHAR(160) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, user_id INT UNIQUE NULL, job_title VARCHAR(120) NOT NULL, department_id INT NOT NULL, tenure_years FLOAT NOT NULL, monthly_income FLOAT NOT NULL, job_satisfaction INT NOT NULL, work_life_balance INT NOT NULL, overtime BOOLEAN NOT NULL, years_since_promotion FLOAT NOT NULL, is_active BOOLEAN NOT NULL, joined_on DATE NOT NULL, FOREIGN KEY(department_id) REFERENCES departments(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE predictions (id INT PRIMARY KEY AUTO_INCREMENT, employee_id INT NOT NULL, risk_percent FLOAT NOT NULL, risk_level VARCHAR(20) NOT NULL, confidence_score FLOAT NOT NULL, model_version VARCHAR(50) NOT NULL, explanation TEXT NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(employee_id) REFERENCES employees(id));
CREATE TABLE interventions (id INT PRIMARY KEY AUTO_INCREMENT, employee_id INT NOT NULL, created_by_id INT NOT NULL, intervention_type VARCHAR(80) NOT NULL, status VARCHAR(20) NOT NULL, notes TEXT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY(employee_id) REFERENCES employees(id), FOREIGN KEY(created_by_id) REFERENCES users(id));
CREATE TABLE shifts (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) UNIQUE NOT NULL, start_time VARCHAR(5) NOT NULL, end_time VARCHAR(5) NOT NULL, break_minutes INT NOT NULL DEFAULT 0, is_active BOOLEAN NOT NULL);
CREATE TABLE shift_assignments (id INT PRIMARY KEY AUTO_INCREMENT, employee_id INT NOT NULL, shift_id INT NOT NULL, assigned_by_id INT NOT NULL, effective_from DATE NOT NULL, FOREIGN KEY(employee_id) REFERENCES employees(id), FOREIGN KEY(shift_id) REFERENCES shifts(id), FOREIGN KEY(assigned_by_id) REFERENCES users(id));
CREATE TABLE attendance_records (id INT PRIMARY KEY AUTO_INCREMENT, employee_id INT NOT NULL, shift_id INT NULL, check_in DATETIME NOT NULL, check_out DATETIME NULL, FOREIGN KEY(employee_id) REFERENCES employees(id), FOREIGN KEY(shift_id) REFERENCES shifts(id));
CREATE TABLE leave_requests (id INT PRIMARY KEY AUTO_INCREMENT, employee_id INT NOT NULL, leave_type VARCHAR(40) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, reason VARCHAR(1000) NOT NULL, status VARCHAR(20) NOT NULL, reviewed_by_id INT NULL, reviewer_notes VARCHAR(1000) NULL, created_at DATETIME NOT NULL, FOREIGN KEY(employee_id) REFERENCES employees(id), FOREIGN KEY(reviewed_by_id) REFERENCES users(id));
CREATE TABLE notifications (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, title VARCHAR(120) NOT NULL, message VARCHAR(1000) NOT NULL, is_read BOOLEAN NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE audit_logs (id INT PRIMARY KEY AUTO_INCREMENT, actor_id INT NOT NULL, action VARCHAR(80) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id INT NULL, details VARCHAR(1000) NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE leave_policies (id INT PRIMARY KEY AUTO_INCREMENT, leave_type VARCHAR(40) NOT NULL, year INT NOT NULL, annual_allowance_days INT NOT NULL, is_active BOOLEAN NOT NULL, created_by_id INT NOT NULL, created_at DATETIME NOT NULL, UNIQUE(leave_type, year), FOREIGN KEY(created_by_id) REFERENCES users(id));
CREATE TABLE payroll_records (id INT PRIMARY KEY AUTO_INCREMENT, employee_id INT NOT NULL, period_start DATE NOT NULL, period_end DATE NOT NULL, base_salary DECIMAL(12,2) NOT NULL, allowances DECIMAL(12,2) NOT NULL DEFAULT 0, bonus DECIMAL(12,2) NOT NULL DEFAULT 0, deductions DECIMAL(12,2) NOT NULL DEFAULT 0, net_pay DECIMAL(12,2) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'Draft', generated_by_id INT NOT NULL, created_at DATETIME NOT NULL, UNIQUE(employee_id, period_start), FOREIGN KEY(employee_id) REFERENCES employees(id), FOREIGN KEY(generated_by_id) REFERENCES users(id));
